// 创建材质
let material = Material::new();
material.set_albedo(Color::rgb(1.0, 0.0, 0.0)); // 红色
material.set_metallic(0.0); // 非金属
material.set_roughness(0.5); // 中等粗糙度

println!("材质创建完成");

